// Dominio: Kotlin puro, niente Android
class SearchUseCase(private val repo: Repo) {
    operator fun invoke(q: String): Flow<List<Item>> =
        repo.search(q).map { it.sortedBy(Item::name) }
}

// UI: chiede quello che le serve, non se lo costruisce
@HiltViewModel
class SearchViewModel @Inject constructor(
    private val search: SearchUseCase
) : ViewModel() {
    private val _state = MutableStateFlow(UiState())
    val state = _state.asStateFlow()
}

